<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue'
import {drawNoteStroke} from './noteDrawing'
import type {NoteTool,NoteStroke,NotePoint,NoteAnnotation} from './noteDrawing'
const props=defineProps<{annotation:NoteAnnotation}>(),emit=defineEmits<{save:[image:Blob,annotation:NoteAnnotation];cancel:[]}>()
const dialog=ref<HTMLDialogElement|null>(null),canvas=ref<HTMLCanvasElement|null>(null),tool=ref<NoteTool>('pen'),color=ref('#ef4444'),size=ref(5),dashed=ref(false),error=ref(''),saving=ref(false),ready=ref(false)
const tools:{value:NoteTool;label:string}[]=[{value:'pen',label:'画笔'},{value:'highlight',label:'荧光笔'},{value:'arrow',label:'箭头'},{value:'rectangle',label:'矩形'},{value:'ellipse',label:'椭圆'},{value:'eraser',label:'橡皮'}]
const strokes=ref<NoteStroke[]>(JSON.parse(JSON.stringify(props.annotation.strokes)) as NoteStroke[]),redo=ref<NoteStroke[]>([])
let image:HTMLImageElement|null=null,url='',overlay:HTMLCanvasElement|null=null,active:NoteStroke|null=null,pointer:number|null=null,disposed=false
function render(){const c=canvas.value,ctx=c?.getContext('2d'),layer=overlay?.getContext('2d');if(!c||!ctx||!layer||!overlay||!image)return;layer.clearRect(0,0,c.width,c.height);for(const stroke of [...strokes.value,...(active?[active]:[])])drawNoteStroke(layer,stroke);ctx.clearRect(0,0,c.width,c.height);ctx.drawImage(image,0,0,c.width,c.height);ctx.drawImage(overlay,0,0)}
function point(e:PointerEvent):NotePoint{const c=canvas.value!,box=c.getBoundingClientRect();return{x:Math.max(0,Math.min(c.width,(e.clientX-box.left)*c.width/box.width)),y:Math.max(0,Math.min(c.height,(e.clientY-box.top)*c.height/box.height))}}
function start(e:PointerEvent){if(!ready.value||!e.isPrimary||e.button!==0||saving.value)return;e.preventDefault();pointer=e.pointerId;canvas.value?.setPointerCapture(pointer);active={tool:tool.value,color:color.value,size:size.value,dashed:dashed.value,points:[point(e)]};render()}
function move(e:PointerEvent){if(pointer!==e.pointerId||!active)return;const p=point(e),last=active.points.at(-1)!;if(Math.hypot(p.x-last.x,p.y-last.y)<.6)return;if(['arrow','rectangle','ellipse'].includes(active.tool))active.points=[active.points[0]!,p];else if(active.points.length<6000)active.points.push(p);render()}
function finish(e:PointerEvent){if(pointer!==e.pointerId||!active)return;move(e);strokes.value.push(active);active=null;pointer=null;redo.value=[];if(canvas.value?.hasPointerCapture(e.pointerId))canvas.value.releasePointerCapture(e.pointerId);render()}
function cancelStroke(){active=null;pointer=null;render()}
function undo(){const s=strokes.value.pop();if(s)redo.value.push(s);render()}
function redoStroke(){const s=redo.value.pop();if(s)strokes.value.push(s);render()}
function clear(){redo.value=[];strokes.value=[];render()}
async function save(){if(!ready.value||saving.value)return;saving.value=true;error.value='';try{const blob=await new Promise<Blob>((resolve,reject)=>canvas.value!.toBlob(b=>b?resolve(b):reject(new Error('export_failed')),'image/png'));emit('save',blob,{base:props.annotation.base,strokes:structuredClone(strokes.value.map(s=>({...s,points:s.points.map(p=>({...p}))})))})}catch{error.value='图片保存失败，请重试；标注仍保留在这里。'}finally{saving.value=false}}
onMounted(async()=>{dialog.value?.showModal();try{url=URL.createObjectURL(props.annotation.base);const picture=new Image();picture.src=url;await picture.decode();if(disposed)return;image=picture;const c=canvas.value!;const scale=Math.min(1,2560/Math.max(picture.naturalWidth,picture.naturalHeight));c.width=Math.round(picture.naturalWidth*scale);c.height=Math.round(picture.naturalHeight*scale);overlay=document.createElement('canvas');overlay.width=c.width;overlay.height=c.height;ready.value=true;render()}catch{error.value='这张图片无法打开，请换一张图片。'}})
onUnmounted(()=>{disposed=true;if(url)URL.revokeObjectURL(url)})
</script>
<template><dialog ref="dialog" class="annotation-dialog" aria-label="标注画面" @cancel.prevent="!saving&&emit('cancel')"><header><div><h3>标注画面</h3><p>画笔、图形与橡皮只修改标注，原画面会保留。</p></div><button type="button" class="secondary" :disabled="saving" @click="emit('cancel')">取消</button></header><div class="annotation-toolbar"><div class="annotation-tools" role="group" aria-label="标注工具"><button v-for="item in tools" :key="item.value" type="button" :aria-pressed="tool===item.value" @click="tool=item.value">{{ item.label }}</button></div><label>颜色<input v-model="color" type="color" aria-label="画笔颜色" /></label><label>粗细<input v-model.number="size" type="range" min="1" max="30" aria-label="画笔粗细" /><span>{{ size }}</span></label><label>样式<select v-model="dashed" aria-label="线条样式"><option :value="false">实线</option><option :value="true">虚线</option></select></label><button type="button" :disabled="!strokes.length||saving" @click="undo">撤销</button><button type="button" :disabled="!redo.length||saving" @click="redoStroke">重做</button><button type="button" :disabled="!strokes.length||saving" @click="clear">清空标注</button></div><div class="annotation-stage"><canvas ref="canvas" aria-label="画面标注画布" @pointerdown="start" @pointermove="move" @pointerup="finish" @pointercancel="cancelStroke" @lostpointercapture="cancelStroke" /></div><p v-if="error" class="annotation-error" role="alert">{{ error }}</p><footer><span>完成后可再添加文字，一起保存到随手笔记。</span><button type="button" class="run" :disabled="!ready||saving" @click="save">{{ saving?'正在处理…':'使用这张图片' }}</button></footer></dialog></template>
<style scoped>
.annotation-dialog{width:min(1200px,96vw);max-width:96vw;max-height:94vh;padding:20px;border:1px solid #d5dff3;border-radius:18px;background:#f7faff;color:#233758;box-sizing:border-box}.annotation-dialog::backdrop{background:#0f1c39a8}.annotation-dialog header,.annotation-dialog footer{display:flex;justify-content:space-between;align-items:center;gap:14px}.annotation-dialog h3{margin:0;font-size:20px}.annotation-dialog p,.annotation-dialog footer span{font-size:12px;color:#607394}.annotation-toolbar{display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:12px 0}.annotation-tools{display:flex;gap:4px;flex-wrap:wrap}.annotation-toolbar button,.annotation-toolbar select{padding:8px 10px;border:1px solid #d6e0f4;border-radius:7px;background:#fff;color:#385078;cursor:pointer}.annotation-toolbar button[aria-pressed=true]{background:#e6edff;border-color:#83a0f1;color:#2855d8}.annotation-toolbar label{display:flex;align-items:center;gap:6px;font-size:12px}.annotation-toolbar input[type=color]{width:32px;height:30px;padding:2px;border:1px solid #cbd6ec;background:white}.annotation-toolbar input[type=range]{width:85px}.annotation-stage{display:flex;align-items:center;justify-content:center;background:#18243b;border-radius:10px;overflow:hidden;min-height:100px}.annotation-stage canvas{display:block;max-width:100%;max-height:60vh;width:auto;height:auto;touch-action:none;cursor:crosshair}.annotation-dialog footer{margin-top:14px}.annotation-error{color:#a94444!important}.annotation-toolbar button:disabled{opacity:.45;cursor:default}@media(max-width:600px){.annotation-dialog{padding:12px}.annotation-dialog footer{align-items:stretch;flex-direction:column}.annotation-stage canvas{max-height:50vh}.annotation-toolbar{gap:8px}}
</style>
